package dev.odin.controls;
import android.app.*;import android.content.*;import android.database.ContentObserver;import android.os.*;import android.provider.Settings;
/** Event-driven Odin 2 restoration; OEM setting changes end ownership. */
public final class ZoneService extends Service {
 static volatile boolean active;final Handler handler=new Handler(Looper.getMainLooper());volatile int generation;volatile int restored=-1;int scheduled=-1;
 void error(Exception e){android.util.Log.e("RavenZones","LED restoration failed",e);ControlNotifications.recovery(this,ControlNotifications.LED_ALERT,"Raven · LED recovery",e.getMessage()==null?"The LED profile could not be restored.":e.getMessage());}
 final Runnable check=new Runnable(){public void run(){if(ZoneSession.writing){handler.postDelayed(this,100);return;}if(!ZoneSession.owned(ZoneService.this))new Thread(()->{try{ZoneSession.release(ZoneService.this);}catch(Exception e){error(e);}},"ZoneStockHandoff").start();}};
 final ContentObserver observer=new ContentObserver(handler){@Override public void onChange(boolean self){handler.removeCallbacks(check);handler.postDelayed(check,300);}};
 void restore(int epoch){if(scheduled==epoch||restored==epoch)return;scheduled=epoch;handler.postDelayed(()->new Thread(()->{if(epoch!=generation)return;try{ZoneSession.resume(this);if(epoch==generation)restored=epoch;android.util.Log.i("RavenZones","Wake restored generation="+epoch);}catch(Exception e){handler.post(()->{if(scheduled==epoch)scheduled=-1;});error(e);}},"ZoneWakeRestore").start(),1200);}
 final BroadcastReceiver screen=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){String a=i.getAction();if(Intent.ACTION_SCREEN_OFF.equals(a)){generation++;new Thread(()->{try{ZoneSession.sleep(ZoneService.this);}catch(Exception e){error(e);}},"ZoneSleep").start();}else if(Intent.ACTION_SCREEN_ON.equals(a))restore(++generation);else if(Intent.ACTION_USER_PRESENT.equals(a))restore(generation);}};
 @Override public void onCreate(){super.onCreate();active=true;ControlNotifications.ensure(this);startForeground(7,ControlNotifications.status(this,ControlNotifications.LED,"Raven LED profiles","Restoring your LED profile after standby").setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class).putExtra("openTab","LEDs"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT)).build());for(String key:DeviceState.LED_KEYS)getContentResolver().registerContentObserver(Settings.System.getUriFor(key),false,observer);IntentFilter f=new IntentFilter(Intent.ACTION_SCREEN_ON);f.addAction(Intent.ACTION_SCREEN_OFF);f.addAction(Intent.ACTION_USER_PRESENT);registerReceiver(screen,f,Context.RECEIVER_NOT_EXPORTED);}
 @Override public int onStartCommand(Intent i,int flags,int id){final int epoch=generation;if(i!=null&&i.getBooleanExtra("applied",false)){restored=epoch;return START_STICKY;}new Thread(()->{try{ZoneSession.resume(this);if(epoch==generation&&getSystemService(PowerManager.class).isInteractive())restored=epoch;}catch(Exception e){error(e);}},"ZoneColdRestore").start();return START_STICKY;}
 @Override public void onDestroy(){active=false;generation++;handler.removeCallbacksAndMessages(null);getContentResolver().unregisterContentObserver(observer);unregisterReceiver(screen);super.onDestroy();}
 @Override public IBinder onBind(Intent i){return null;}
}
